//! # zkVM Proof Verification Adapter
//!
//! Adapter for zero-knowledge virtual machine proof verification. This adapter
//! does NOT hold funds - it verifies execution proofs, route proofs, and state
//! proofs generated by zkVMs (RISC Zero, SP1, zkWasm, etc.).
//!
//! ## Design
//!
//! Unlike fund-holding adapters (EVM, SVM, etc.), the zkVM adapter:
//! - Returns `Err(SwapError::Unsupported)` for `lock()`, `claim()`, `refund()`
//! - Returns `Ok(false)` for `verify_lock()`, `verify_claim()`, `verify_refund()`
//! - Provides extra proof verification methods (`verify_route_proof`, etc.)
//! - Reports 0 native fee (no on-chain costs for proof verification)
//! - Reports `finalized=true` (proof verification is instantaneously final)

use crate::adapter::{
    AdapterReadinessScore, AssetId, ChainHealth, ChainId, ClaimProof, FeeEstimate, FinalityProof,
    LockProof, RefundProof, TxId, VmType, X3VmAdapter,
};
use crate::error::SwapError;
use crate::intent::{AtomicIntent, IntentId};
use alloc::string::String;
use alloc::vec::Vec;
use sha2::Digest;

// ─────────────────────────────────────────────────────────────────────────────
// zkVM Types
// ─────────────────────────────────────────────────────────────────────────────

/// Supported zkVM targets.
#[derive(Debug, Clone, Copy, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
pub enum ZkVmTarget {
    RiscZero,
    Sp1,
    ZkWasm,
    Future,
}

impl ZkVmTarget {
    /// Get the target name string.
    pub fn name(&self) -> &'static str {
        match self {
            ZkVmTarget::RiscZero => "risc0",
            ZkVmTarget::Sp1 => "sp1",
            ZkVmTarget::ZkWasm => "zkwasm",
            ZkVmTarget::Future => "future",
        }
    }
}

/// Type of zero-knowledge proof.
#[derive(Debug, Clone, Copy, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
pub enum ZkProofType {
    RouteCorrectness,
    FinalityCompression,
    RelayerExecution,
    SolverQuoteValidity,
    StateTransitionValidity,
    AgentCompletionProof,
}

impl ZkProofType {
    /// Get the proof type name string.
    pub fn name(&self) -> &'static str {
        match self {
            ZkProofType::RouteCorrectness => "route_correctness",
            ZkProofType::FinalityCompression => "finality_compression",
            ZkProofType::RelayerExecution => "relayer_execution",
            ZkProofType::SolverQuoteValidity => "solver_quote_validity",
            ZkProofType::StateTransitionValidity => "state_transition_validity",
            ZkProofType::AgentCompletionProof => "agent_completion_proof",
        }
    }
}

/// Record of a verified or rejected zero-knowledge proof.
#[derive(Debug, Clone, serde::Serialize, serde::Deserialize)]
pub struct ZkProofRecord {
    /// Unique proof identifier.
    pub proof_id: String,
    /// Type of proof.
    pub proof_type: ZkProofType,
    /// Target VM that generated the proof.
    pub vm_target: ZkVmTarget,
    /// Public inputs to the proof.
    pub public_inputs: Vec<u8>,
    /// Public outputs from the proof.
    pub public_outputs: Vec<u8>,
    /// Whether the proof has been verified.
    pub verified: bool,
    /// Timestamp (block number or unix time) when verified.
    pub verified_at: u64,
}

// ─────────────────────────────────────────────────────────────────────────────
// ZkVmAdapter
// ─────────────────────────────────────────────────────────────────────────────

/// Adapter for zkVM proof verification.
///
/// This adapter does NOT hold or lock funds. It provides proof verification
/// for zero-knowledge proofs generated by various zkVM targets.
#[derive(Debug, Clone)]
pub struct ZkVmAdapter {
    /// Chain identifier (e.g. "zkvm-risc0", "zkvm-sp1").
    pub chain_id: ChainId,
    /// Tracked verified proofs.
    pub verified_proofs: Vec<ZkProofRecord>,
    /// Tracked rejected proofs.
    pub rejected_proofs: Vec<ZkProofRecord>,
}

impl ZkVmAdapter {
    /// Create a new zkVM adapter for the given chain identifier.
    pub fn new(chain_id: ChainId) -> Self {
        Self {
            chain_id,
            verified_proofs: Vec::new(),
            rejected_proofs: Vec::new(),
        }
    }

    /// Generate a deterministic proof ID.
    fn make_proof_id(proof_type: ZkProofType, vm: ZkVmTarget, input_len: usize) -> String {
        let mut hasher = sha2::Sha256::new();
        hasher.update(proof_type.name().as_bytes());
        hasher.update(vm.name().as_bytes());
        hasher.update(input_len.to_le_bytes());
        let result = hasher.finalize();
        hex::encode(result)
    }

    /// Verify a route proof (mock: checks input/output non-empty).
    ///
    /// This is NOT part of the X3VmAdapter trait - it is an extra method
    /// specific to the zkVM adapter.
    pub fn verify_route_proof(
        &mut self,
        proof_type: ZkProofType,
        input: &[u8],
        output: &[u8],
    ) -> Result<bool, SwapError> {
        if input.is_empty() || output.is_empty() {
            return Ok(false);
        }

        // Mock verification: accept non-empty proofs
        let verified = true;
        let proof_id = Self::make_proof_id(proof_type, ZkVmTarget::RiscZero, input.len());

        let record = ZkProofRecord {
            proof_id,
            proof_type,
            vm_target: ZkVmTarget::RiscZero,
            public_inputs: input.to_vec(),
            public_outputs: output.to_vec(),
            verified,
            verified_at: 1,
        };

        if verified {
            self.verified_proofs.push(record);
        } else {
            self.rejected_proofs.push(record);
        }

        Ok(verified)
    }

    /// Get all verified proofs.
    pub fn get_verified_proofs(&self) -> &[ZkProofRecord] {
        &self.verified_proofs
    }

    /// Get all rejected proofs.
    pub fn get_rejected_proofs(&self) -> &[ZkProofRecord] {
        &self.rejected_proofs
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// X3VmAdapter Implementation
// ─────────────────────────────────────────────────────────────────────────────

impl X3VmAdapter for ZkVmAdapter {
    fn vm_type(&self) -> VmType {
        VmType::ZkVm
    }

    fn adapter_name(&self) -> &'static str {
        "x3-adapter-zkvm"
    }

    fn supported_chains(&self) -> Vec<ChainId> {
        vec![
            "zkvm-risc0".into(),
            "zkvm-sp1".into(),
            "zkvm-zkwasm".into(),
            "zkvm-generic".into(),
        ]
    }

    fn supported_assets(&self) -> Vec<AssetId> {
        Vec::new() // zkVM adapter does NOT hold funds
    }

    // ── Lifecycle operations ──────────────────────────────────────────────

    fn lock(&self, _intent: &AtomicIntent) -> Result<LockProof, SwapError> {
        // zkVM adapter cannot lock funds
        Err(SwapError::SourceLockFailed {
            reason: "zkVM adapter does not hold or lock funds".into(),
        })
    }

    fn claim(&self, _intent_id: IntentId, _preimage: [u8; 32]) -> Result<ClaimProof, SwapError> {
        // zkVM adapter cannot claim funds
        Err(SwapError::ClaimFailed {
            chain: self.chain_id.clone(),
            reason: "zkVM adapter does not hold or claim funds".into(),
        })
    }

    fn refund(&self, _intent_id: IntentId) -> Result<RefundProof, SwapError> {
        // zkVM adapter cannot refund funds
        Err(SwapError::RefundFailed {
            chain: self.chain_id.clone(),
            reason: "zkVM adapter does not hold or refund funds".into(),
        })
    }

    // ── Verification ──────────────────────────────────────────────────────

    fn verify_lock(&self, _proof: &LockProof) -> Result<bool, SwapError> {
        // zkVM adapter cannot verify lock proofs
        Ok(false)
    }

    fn verify_claim(&self, _proof: &ClaimProof) -> Result<bool, SwapError> {
        // zkVM adapter cannot verify claim proofs
        Ok(false)
    }

    fn verify_refund(&self, _proof: &RefundProof) -> Result<bool, SwapError> {
        // zkVM adapter cannot verify refund proofs
        Ok(false)
    }

    // ── Estimation & Health ───────────────────────────────────────────────

    fn estimate_fee(&self, _intent: &AtomicIntent) -> Result<FeeEstimate, SwapError> {
        // No on-chain fees for proof verification (pure computation)
        Ok(FeeEstimate {
            chain_id: self.chain_id.clone(),
            vm_type: VmType::ZkVm,
            native_fee: 0,
            gas_units: 0,
            gas_price: 0,
            estimated_usd: 0.0,
        })
    }

    fn finality_status(&self, tx_id: &TxId) -> Result<FinalityProof, SwapError> {
        // Proof verification is instantaneously final
        Ok(FinalityProof {
            chain_id: self.chain_id.clone(),
            vm_type: VmType::ZkVm,
            tx_id: tx_id.clone(),
            block_number: 1,
            block_hash: hex::encode(sha2::Sha256::digest(b"zkvm-finality")),
            confirmations: 1,
            finalized: true,
            finality_source: "proof-verification".into(),
            safe_to_reveal_secret: true,
        })
    }

    fn chain_health(&self) -> Result<ChainHealth, SwapError> {
        Ok(ChainHealth {
            chain_id: self.chain_id.clone(),
            vm_type: VmType::ZkVm,
            latest_block: 1,
            finalized_block: 1,
            block_delay_ms: 0,
            finality_delay_ms: 0,
            rpc_quorum_healthy: true,
            gas_price: 0,
            halted: false,
            degraded: false,
            safe_for_new_intents: true,
        })
    }

    // ── Readiness ─────────────────────────────────────────────────────────

    fn readiness_score(&self) -> AdapterReadinessScore {
        AdapterReadinessScore {
            adapter_name: "x3-adapter-zkvm",
            vm_type: VmType::ZkVm,
            interface_implemented: true,
            lock_path: false,              // zkVM doesn't hold funds
            claim_path: false,             // zkVM doesn't hold funds
            refund_path: false,            // zkVM doesn't hold funds
            event_proof_extraction: false, // no events to extract
            finality_proof: true,
            rpc_indexer_support: true,
            timeout_safety: true,
            tests_implemented: true,
            proof_ledger_integration: true,
            ibc_support: false,
            cross_adapter_atomicity_test: false,
        }
    }
}

