    // ── Lock Returns Error Tests ──────────────────────────────────────────

    #[test]
    fn test_lock_returns_unsupported() {
        let adapter = ZkVmAdapter::new("zkvm-risc0".into());
        let hashlock = make_hashlock(b"test");
        let intent = make_test_intent(1, hashlock);

        let result = adapter.lock(&intent);
        assert!(result.is_err(), "zkVM adapter should not support lock");
        match result {
            Err(SwapError::SourceLockFailed { reason }) => {
                assert!(reason.contains("does not hold"), "reason: {}", reason);
            }
            other => panic!("Expected SourceLockFailed, got {:?}", other),
        }
    }

