    // ── Proof Tracking Tests ──────────────────────────────────────────────

    #[test]
    fn test_verified_proofs_tracked() {
        let mut adapter = ZkVmAdapter::new("zkvm-risc0".into());

        assert!(adapter.get_verified_proofs().is_empty());
        assert!(adapter.get_rejected_proofs().is_empty());

        adapter
            .verify_route_proof(ZkProofType::RouteCorrectness, b"in", b"out")
            .expect("verify");

        assert_eq!(adapter.get_verified_proofs().len(), 1);
        assert_eq!(adapter.get_rejected_proofs().len(), 0);

        let record = &adapter.get_verified_proofs()[0];
        assert_eq!(record.proof_type, ZkProofType::RouteCorrectness);
        assert!(record.verified);
    }

    #[test]
    fn test_rejected_proofs_tracked() {
        let mut adapter = ZkVmAdapter::new("zkvm-sp1".into());

        // Empty input -> rejected
        adapter
            .verify_route_proof(ZkProofType::FinalityCompression, &[], b"out")
            .expect("verify");

        assert_eq!(adapter.get_verified_proofs().len(), 0);
        assert_eq!(adapter.get_rejected_proofs().len(), 0); // rejected early, not tracked

        // Verified proofs tracked correctly
        adapter
            .verify_route_proof(ZkProofType::RouteCorrectness, b"in", b"out")
            .expect("verify");

        assert_eq!(adapter.get_verified_proofs().len(), 1);
    }

    #[test]
    fn test_multiple_proofs_tracked() {
        let mut adapter = ZkVmAdapter::new("zkvm-risc0".into());

        for i in 0..5 {
            let input = alloc::format!("input_{}", i);
            let output = alloc::format!("output_{}", i);
            adapter
                .verify_route_proof(
                    ZkProofType::RouteCorrectness,
                    input.as_bytes(),
                    output.as_bytes(),
                )
                .expect("verify");
        }

        assert_eq!(adapter.get_verified_proofs().len(), 5);
    }

